# ---------- assemble
shots = []
starts = []
for i, (line, w, p, ex) in enumerate(L):
    st = 0.0 if i == 0 else max(0, round(t_of(line, w) - 0.15, 2))
    starts.append(st)
for i in range(1, len(starts)):
    if starts[i] <= starts[i - 1] + 0.3: raise SystemExit(f'shot {i} starts too close to previous: {L[i][0]} {L[i][1]} {starts[i]} vs {starts[i-1]}')
for i, (line, w, p, ex) in enumerate(L):
    st, en = starts[i], (starts[i + 1] if i + 1 < len(L) else DUR)
    sid = f's{i + 1:03d}'
    setn = p.get('set', 'void'); p = dict(p)
    if setn == 'streetDay': p['set'] = 'street'; p['so'] = {'mood': 'day', **p.get('so', {})}
    if p.get('tpl') == '3d': setn = 'street' if p.get('s3') == 'town' else 'hall'
    lines = [s['text'] for s in SENT if s['start'] >= st - 0.05 and s['start'] < en - 0.1]
    amb = AMB.get('cls' if setn == 'class' else setn, ('roomtone', -32))
    shot = dict(id=sid, start=st, end=en, line=' '.join(lines), scene=f"{p.get('tpl')} {p.get('obj') or p.get('d') or p.get('who') or p.get('s3') or ''} @ {setn}".strip(), set=setn,
                bars=ex['bars'], **{'in': ex['tr'] or {'type': 'cut'}}, sfx=[s for s in ex['sfx'] if s['at'] < en - st], amb=dict(name=amb[0], gain=amb[1]), params=p)
    if ex['mb']: shot['mb'] = ex['mb']
    shots.append(shot)

music = [dict(start=0, end=52, mood='playful', intensity=0.45), dict(start=52, end=103.5, mood='wonder', intensity=0.45), dict(start=103.5, end=177, mood='playful', intensity=0.5),
         dict(start=177, end=180, mood='sad', intensity=0.3), dict(start=180, end=340, mood='playful', intensity=0.55), dict(start=340, end=362.5, mood='hopeful', intensity=0.5),
         dict(start=362.5, end=418.5, mood='mystery', intensity=0.35), dict(start=418.5, end=467.5, mood='sad', intensity=0.3), dict(start=467.5, end=473, mood='dark', intensity=0.4),
         dict(start=473, end=546, mood='hopeful', intensity=0.4), dict(start=546, end=578, mood='mystery', intensity=0.45), dict(start=578, end=644, mood='tension', intensity=0.55),
         dict(start=644, end=700, mood='tension', intensity=0.75), dict(start=700, end=760, mood='sad', intensity=0.4), dict(start=760, end=806, mood='calm', intensity=0.35),
         dict(start=806, end=833, mood='triumph', intensity=0.5), dict(start=833, end=846.5, mood='mystery', intensity=0.5), dict(start=846.5, end=922.5, mood='wonder', intensity=0.35),
         dict(start=922.5, end=DUR, mood='hopeful', intensity=0.4)]
out = dict(title='What If You Could Win Every Argument?', duration=DUR, shots=shots, music=music, sfx=[])
json.dump(out, open(os.path.join(HERE, 'shots.json'), 'w'), indent=1)
d = [s['end'] - s['start'] for s in shots]; d.sort()
print(f'{len(shots)} shots, duration {DUR}, median {d[len(d)//2]:.2f}s, min {d[0]:.2f}, max {d[-1]:.2f}')
long_ = [(s['id'], round(s['end'] - s['start'], 1)) for s in shots if s['end'] - s['start'] > 7]
print('long shots:', long_)
